/// Raven `SP_gametype_item`.
///
/// Source: `oracle/oracle/codemp/game/g_spawn.c:372-431`
pub fn SP_gametype_item(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let mut value: *mut c_char = std::ptr::null_mut();
        G_SpawnString(ctx, c"teamfilter".as_ptr(), c"".as_ptr(), &mut value);

        G_SetOrigin(ent, (*ent).s.origin);

        // If a team filter is set then override any team settings for the spawns
        let mut team: c_int = -1;
        let mTeamFilter = (*ctx.world).level.mTeamFilter.as_ptr();
        if *mTeamFilter != 0 {
            if Q_stricmp(mTeamFilter, c"red".as_ptr()) == 0 {
                team = TEAM_RED;
            } else if Q_stricmp(mTeamFilter, c"blue".as_ptr()) == 0 {
                team = TEAM_BLUE;
            }
        }

        let mut item: *mut gitem_t = std::ptr::null_mut();
        if !(*ent).targetname.is_null() && *(*ent).targetname != 0 {
            let targetname = CStr::from_ptr((*ent).targetname).to_string_lossy();
            if team != -1 {
                if targetname.contains("flag") {
                    item = if team == TEAM_RED {
                        BG_FindItem(c"team_CTF_redflag".as_ptr())
                    } else {
                        // blue
                        BG_FindItem(c"team_CTF_blueflag".as_ptr())
                    };
                }
            } else if targetname.contains("red_flag") {
                item = BG_FindItem(c"team_CTF_redflag".as_ptr());
            } else if targetname.contains("blue_flag") {
                item = BG_FindItem(c"team_CTF_blueflag".as_ptr());
            } else {
                item = std::ptr::null_mut();
            }

            if !item.is_null() {
                (*ent).targetname = std::ptr::null_mut();
                (*ent).classname = (*item).classname;
                G_SpawnItem(ctx, ent, item);
            }
        }
    }
}

/// Raven `G_CallSpawn`.
///
/// Finds the spawn function for the entity and calls it, returning `qfalse`
/// if not found. Checks item spawn functions first (from `bg_itemlist`), then
/// normal spawn functions (from `spawns[]` table).
///
/// Source: `oracle/oracle/codemp/game/g_spawn.c:683-714`
pub fn G_CallSpawn(ctx: GameContext<'_>, ent: *mut gentity_t) -> qboolean {
    unsafe {
        if (*ent).classname.is_null() {
            G_Printf(ctx, c"G_CallSpawn: NULL classname\n".as_ptr());
            return QFALSE;
        }

        // check item spawn functions
        let mut item = bg_itemlist.add(1);
        while !(*item).classname.is_null() {
            if Q_stricmp((*item).classname, (*ent).classname) == 0 {
                G_SpawnItem(ctx, ent, item);
                return QTRUE;
            }
            item = item.add(1);
        }

        // check normal spawn functions
        let mut s = spawns.as_ptr();
        while !(*s).name.is_null() {
            if Q_stricmp((*s).name, (*ent).classname) == 0 {
                // found it
                if !(*ent).healingsound.is_null() && *(*ent).healingsound != 0 {
                    //yeah...this can be used for anything, so.. precache it if it's there
                    G_SoundIndex((*ent).healingsound);
                }
                ((*s).spawn)(ent);
                return QTRUE;
            }
            s = s.add(1);
        }
        G_Printf(
            ctx,
            c"%s doesn't have a spawn function\n".as_ptr(),
            (*ent).classname,
        );
        QFALSE
    }
}

/// Raven `G_NewString` — builds a copy of the string, translating `\n` to
/// real linefeeds so message texts can be multi-line.
///
/// Source: `oracle/oracle/codemp/game/g_spawn.c:724-749`
pub fn G_NewString(string: *const c_char) -> *mut c_char {
    unsafe {
        let mut l = 0isize;
        while *string.offset(l) != 0 {
            l += 1;
        }
        l += 1; // + 1 for the NUL, matching `strlen(string) + 1`

        let newb = G_Alloc(l as c_int) as *mut c_char;
        let mut new_p = newb;

        let mut i: isize = 0;
        while i < l {
            let c = *string.offset(i);
            if c == b'\\' as c_char && i < l - 1 {
                i += 1;
                let c2 = *string.offset(i);
                if c2 == b'n' as c_char {
                    *new_p = b'\n' as c_char;
                } else {
                    *new_p = b'\\' as c_char;
                }
                new_p = new_p.offset(1);
            } else {
                *new_p = c;
                new_p = new_p.offset(1);
            }
            i += 1;
        }

        newb
    }
}

